const received = [];
const sentinel = new Error('"'consumer failed');
try {
  await streamChat({ messages: [{role:'user',content:'hello'}] }, text => {
    received.push(text);
    if (received.length === 1) throw sentinel;
  });
  console.log(JSON.stringify({result:'resolved',received}));
} catch (err) {
  console.log(JSON.stringify({result:'rejected',sameError:err===sentinel,received}));
} finally {
  globalThis.fetch = nativeFetch;
  server.closeAllConnections();
  await new Promise(resolve => server.close(resolve));
}
